pts=[(y,x,v) for y,row in enumerate(mask,1) for x,v in enumerate(row,1)]
# simple bit predicate threshold from shifts and ops
best=[]
for ay in range(-3,4):
 for ax in range(-3,4):
  for op in ['and0','or0','eq','xorodd','andodd','popxor','sumpar','prodpar']:
   preds=[]
   for y,x,v in pts:
    a=y+ay;b=x+ax
    if a<0 or b<0: q=None
    elif op=='and0':q=int((a&b)==0)
    elif op=='or0':q=int((a|b)==0)
    elif op=='eq':q=int(a==b)
    elif op=='xorodd':q=(a^b)&1
    elif op=='andodd':q=(a&b)&1
    elif op=='popxor':q=(a.bit_count()^b.bit_count())&1
    elif op=='sumpar':q=(a+b)&1
    elif op=='prodpar':q=(a*b)&1
    if q is not None: preds.append((q,v))
   hit=sum(q==v for q,v in preds)
   if len(preds)>0: best.append((hit/len(preds),op,ay,ax,hit,len(preds)))
print(sorted(best,reverse=True)[:20])

